import {RenderFrameContext,RenderView,Entity,GPUResourceTracker,createGPUResourceOwner} from '/engine/dist/experimental.js';
import {RttEngine} from '/engine/dist/rtt.js';
import {SceneOutputPass} from '/region-target-build/region-copy.js';
import {setPostProcessSubmission} from '/region-target-build/region-submission.js';
const cases=[],errors=[],result=document.querySelector('#result'),progress=document.querySelector('#progress');
const check=(value,message)=>{if(!value)throw Error(message)},colors=[[2,.5,.125,1],[.125,1.5,.75,1]],width=16,height=16;
let device;
try{
 const adapter=await navigator.gpu.requestAdapter({powerPreference:'high-performance'});check(adapter&&!adapter.info.isFallbackAdapter,'Native WebGPU required');device=await adapter.requestDevice();device.pushErrorScope('validation');device.addEventListener('uncapturederror',event=>errors.push(event.error.message));
 const tracker=new GPUResourceTracker({debug:true});tracker.instrumentDevice(device,createGPUResourceOwner('system','g04-submission'));
 const sources=colors.map((color,index)=>{const texture=device.createTexture({label:`submission-source-${index}`,size:[width,height],format:'rgba16float',usage:GPUTextureUsage.TEXTURE_BINDING|GPUTextureUsage.RENDER_ATTACHMENT}),encoder=device.createCommandEncoder(),pass=encoder.beginRenderPass({colorAttachments:[{view:texture.createView(),loadOp:'clear',storeOp:'store',clearValue:color}]});pass.end();device.queue.submit([encoder.finish()]);return texture});
 async function pixels(texture){const read=device.createBuffer({label:'submission-read',size:256*height,usage:GPUBufferUsage.COPY_DST|GPUBufferUsage.MAP_READ}),encoder=device.createCommandEncoder();encoder.copyTextureToBuffer({texture},{buffer:read,bytesPerRow:256},[width,height]);device.queue.submit([encoder.finish()]);await read.mapAsync(GPUMapMode.READ);const raw=new Uint8Array(read.getMappedRange()),bytes=new Uint8Array(width*height*4);for(let y=0;y<height;y++)bytes.set(raw.subarray(y*256,y*256+width*4),y*width*4);read.unmap();read.destroy();return bytes;}
 const expected=(source,exposure,tone)=>colors[source].map((value,index)=>{if(index===3)return 255;let linear=value*exposure;if(tone==='reinhard')linear/=1+linear;const display=linear<=.0031308?linear*12.92:1.055*linear**(1/2.4)-.055;return Math.round(Math.min(1,Math.max(0,display))*255)});
 for(const sampleCount of [1,4])for(const scenario of ['out-of-order','same-encoder','shared-cancel','source-change','cancel-replaced','submitted-reuse']){
  const id=`${scenario}-${sampleCount}`;progress.textContent=id;
  const engine={device,width,height,displayWidth:width,displayHeight:height,format:'rgba8unorm',getDepthFormat:()=> 'depth24plus'},targets=[0,1].map(i=>new RttEngine(engine,width,height,{r:1,g:0,b:1,a:1},`${id}-${i}`,null,'rgba8unorm'));targets.forEach(target=>{target.msaaSamples=sampleCount});
  const views=targets.map(target=>new RenderView({key:'same-view',camera:new Entity('camera'),target,sampleCount})),pass=new SceneOutputPass();pass.prepare(device);
  const contexts=views.map(view=>new RenderFrameContext(engine,{view})),specs=[{source:0,exposure:.25,tone:'reinhard'},{source:0,exposure:2,tone:'none'}];let frame=0;
  const record=(context,index)=>{const spec=specs[index];setPostProcessSubmission(pass,cb=>context.afterSubmit(cb),cb=>context.afterCancel(cb));try{pass.configure('rgba8unorm',spec.exposure,spec.tone,views[index].snapshot());pass.setFrameIdentity(++frame,'same-view');pass.apply(context.encoder,sources[spec.source],targets[index].getOutputView(),device);return pass._bindings.get('same-view').uniform}finally{setPostProcessSubmission(pass)}};
  let selected=[0,1];
  if(scenario==='shared-cancel'){specs[1]={...specs[0]};const first=record(contexts[0],0),second=record(contexts[1],1);check(first===second,'Identical pending output must share immutable parameters');pass.destroy();contexts[0].cancel();contexts[1].submit();selected=[1];}
  else if(scenario==='same-encoder'){record(contexts[0],0);record(contexts[0],1);pass.destroy();contexts[1].cancel();contexts[0].submit();}
  else if(scenario==='submitted-reuse'){const first=record(contexts[0],0);contexts[0].submit();const second=record(contexts[1],1);check(first===second,'Submitted output should reuse parameter capacity');contexts[1].submit();pass.destroy();}
  else{if(scenario==='source-change')specs[1]={...specs[0],source:1};const first=record(contexts[0],0),second=record(contexts[1],1);if(scenario==='source-change')check(first===second,'Immutable groups can share unchanged parameters');else check(first!==second,'Changed pending parameters need a snapshot');pass.destroy();if(scenario==='cancel-replaced'){contexts[0].cancel();selected=[1];contexts[1].submit()}else{contexts[1].submit();contexts[0].submit()}}
  let maximum=0,channels=0;const comparisons=[];
  for(const index of selected){const bytes=await pixels(targets[index].colorTexture),spec=specs[index],reference=expected(spec.source,spec.exposure,spec.tone);let bad=0,max=0;for(let i=0;i<bytes.length;i++){const difference=Math.abs(bytes[i]-reference[i%4]);max=Math.max(max,difference);if(difference>2)bad++}check(!bad,`${id} target${index}: ${bad} channels differ, maximum ${max}`);maximum=Math.max(maximum,max);channels+=bytes.length;comparisons.push({index,...spec,expected:reference,firstPixel:[...bytes.slice(0,4)]});}
  targets.forEach(target=>target.destroy());views.forEach(view=>view.destroy());await device.queue.onSubmittedWorkDone();await Promise.resolve();const resources=tracker.getDebugSnapshot().byType;check((resources.buffer?.current??0)===0,`${id}: parameter/readback buffers remain`);check((resources.texture?.current??0)===sources.length,`${id}: output textures remain`);
  cases.push({id,sampleCount,channelsCompared:channels,maxChannelDifference:maximum,comparisons,buffersAfterCleanup:resources.buffer?.current??0,texturesAfterCleanup:resources.texture?.current??0});
 }
 sources.forEach(source=>source.destroy());await device.queue.onSubmittedWorkDone();const scoped=await device.popErrorScope();if(scoped)errors.push(scoped.message);check(!errors.length,errors.join('\n'));const resources=tracker.getDebugSnapshot().byType;check((resources.buffer?.current??0)===0&&(resources.texture?.current??0)===0,'Final GPU resource residue');
 result.textContent=JSON.stringify({status:'passed',caseCount:cases.length,cases,adapter:{vendor:adapter.info.vendor,architecture:adapter.info.architecture,device:adapter.info.device,description:adapter.info.description,isFallbackAdapter:adapter.info.isFallbackAdapter},errors,resourceResidue:resources,gpuDuration:{status:'not-measured'},qualification:'Native managed SceneOutputPass parameter/queue lifecycle diagnostic; independent CPU display-transform oracle; not complete GUI/3D resource or release qualification'});result.dataset.status='passed';
}catch(error){result.textContent=JSON.stringify({status:'failed',caseCount:cases.length,cases,error:String(error.stack??error),errors});result.dataset.status='failed'}finally{device?.destroy()}
